import{_ as i,o as e,c as t,ae as r}from"./chunks/framework.Bwt6MOeu.js";const m=JSON.parse('{"title":"Platform Human Protection and Safeguarding","description":"","frontmatter":{},"headers":[],"relativePath":"guide/platform-human-protection-and-safeguarding.md","filePath":"guide/platform-human-protection-and-safeguarding.md"}'),n={name:"guide/platform-human-protection-and-safeguarding.md"};function o(l,a,s,c,d,u){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="platform-human-protection-and-safeguarding" tabindex="-1">Platform Human Protection and Safeguarding <a class="header-anchor" href="#platform-human-protection-and-safeguarding" aria-label="Permalink to &quot;Platform Human Protection and Safeguarding&quot;">​</a></h1><p>SocioProphet is designed in favor of protecting humans first.</p><p>This is not a decorative principle. It is the operating rule for the platform.</p><h2 id="core-commitments" tabindex="-1">Core commitments <a class="header-anchor" href="#core-commitments" aria-label="Permalink to &quot;Core commitments&quot;">​</a></h2><p>The platform protects:</p><ul><li>human agency over machine substitution</li><li>minors and vulnerable participants over convenience</li><li>traceability over opaque automation</li><li>bounded capability over unrestricted execution</li><li>recovery and escalation over silent failure</li></ul><h2 id="platform-defaults" tabindex="-1">Platform defaults <a class="header-anchor" href="#platform-defaults" aria-label="Permalink to &quot;Platform defaults&quot;">​</a></h2><p>SocioProphet defaults to:</p><ul><li>least privilege</li><li>role-aware access</li><li>explicit capability gating</li><li>visible recovery states</li><li>attributable actions</li><li>documented escalation paths</li><li>safer defaults for minors, guardians, and institutions</li></ul><h2 id="human-first-design-rule" tabindex="-1">Human-first design rule <a class="header-anchor" href="#human-first-design-rule" aria-label="Permalink to &quot;Human-first design rule&quot;">​</a></h2><p>Humans decide ends, approvals, and legitimacy.</p><p>Machines assist with bounded means under visible policy, evidence, and audit constraints.</p><h2 id="minor-safe-design-rule" tabindex="-1">Minor-safe design rule <a class="header-anchor" href="#minor-safe-design-rule" aria-label="Permalink to &quot;Minor-safe design rule&quot;">​</a></h2><p>Minor access is never treated as a normal low-friction consumer flow.</p><p>Minor participation is governed by:</p><ul><li>guardian-linked or institution-governed participation</li><li>explicit capability restrictions</li><li>stronger reporting and escalation pathways</li><li>elevated consent and review expectations</li></ul><h2 id="surface-implications" tabindex="-1">Surface implications <a class="header-anchor" href="#surface-implications" aria-label="Permalink to &quot;Surface implications&quot;">​</a></h2><p>Every first-class surface must explain:</p><ul><li>who it is for</li><li>what trust boundary it crosses</li><li>what safety restrictions apply</li><li>what recovery and escalation path exists</li></ul><p>This is part of the product contract, not optional documentation.</p>',20)])])}const f=i(n,[["render",o]]);export{m as __pageData,f as default};
